code='''from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(grid[r][c] for r in range(3, h) for c in range(3, w) if grid[r][c] != 0)
    palette = {v for v, n in counts.items() if n >= 5}
    k = len(palette)
    if not k:
        raise ValueError("Could not infer pattern palette")
    by_phase = defaultdict(Counter)
    for r in range(3, h):
        for c in range(3, w):
            v = grid[r][c]
            if v in palette:
                by_phase[(r + c) % k][v] += 1
    phase_color = {p: by_phase[p].most_common(1)[0][0] for p in range(k)}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2:
                out[r][c] = 1
            elif r == 2:
                out[r][c] = 4
            elif c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            else:
                out[r][c] = phase_color[(r + c) % k]
    return out
'''
